APG_SOURCE = '// ============================================================================\n// Fintech Platform — APG Capability Composition Example\n//\n// Composability pattern: Pipeline + Layered\n//   KYC must complete before payments can be processed\n//   AML screens every transaction in the pipeline\n//   Wallets and Lending are downstream of Payments\n//\n// Africa-first: M-Pesa, mobile money, CBK regulatory compliance\n//\n// Copyright (c) 2025 Datacraft — Nyimbi Odero\n// ============================================================================\n\nmodule fintech_platform version 1.0.0 {\n    description: "Africa-first fintech platform — KYC, Payments, Wallets, Lending, AML";\n    author: "Datacraft";\n}\n\ntable Customer {\n    customer_id: str;\n    phone: str;          // primary identifier for mobile money\n    national_id: str;\n    full_name: str;\n    kyc_tier: str;       // basic | standard | full_kyc | enhanced\n    kyc_status: str;     // pending | verified | rejected | expired\n    risk_level: str;     // low | medium | high | very_high\n    daily_limit: decimal;\n    monthly_limit: decimal;\n    currency: str;\n}\n\ntable Wallet {\n    wallet_id: str;\n    customer_id: str;\n    wallet_type: str;   // main | savings | escrow | merchant\n    balance: decimal;\n    currency: str;\n    status: str;        // active | frozen | suspended | closed\n    daily_used: decimal;\n    monthly_used: decimal;\n}\n\ntable Transaction {\n    transaction_id: str;\n    transaction_type: str; // payment | transfer | withdrawal | deposit | reversal\n    channel: str;          // mpesa | mtn_momo | airtel | card | bank_eft | swift\n    amount: decimal;\n    currency: str;\n    sender_id: str;\n    recipient_id: str;\n    reference: str;\n    status: str;           // pending | completed | failed | reversed\n    aml_status: str;       // cleared | flagged | under_review | blocked\n    fee: decimal;\n}\n\ncapability FintechCore {\n    contract: {\n        id: fintech_platform_core,\n        provides: [\n            customer_onboarding_workflow,\n            payment_processing_workflow,\n            wallet_lifecycle,\n            credit_origination_workflow,\n            aml_screening_workflow,\n            regulatory_reporting\n        ],\n        requires: [auth, audl, ntfy, kyc_verification, aml_detection, comp],\n        configuration: {\n            tenant_id: "default",\n            base_currency: "KES",\n            supported_currencies: ["KES", "UGX", "TZS", "USD"],\n            kyc_required_for_payment: true,\n            aml_screen_all: true,\n            cbk_reporting_threshold: 1000000,\n            daily_limit_basic: 300000,\n            daily_limit_standard: 1000000,\n            daily_limit_full_kyc: 5000000,\n            mpesa_business_short_code: "174379",\n            require_liveness_for_full_kyc: true\n        },\n        rule_engine: {\n            type: deterministic,\n            default_decision: allow,\n            rules: [\n                {name: "kyc_required_for_payment",\n                 when: "kyc_status != verified",\n                 action: deny},\n                {name: "basic_kyc_daily_limit",\n                 when: "kyc_tier == basic and transaction_amount + daily_used_gt == 300000",\n                 action: deny},\n                {name: "aml_flagged_transaction_blocked",\n                 when: "aml_status == flagged",\n                 action: deny},\n                {name: "ctr_threshold_requires_report",\n                 when: "amount_gt == 1000000",\n                 action: require_review},\n                {name: "sanctioned_entity_denied",\n                 when: "sanctions_match == true",\n                 action: deny},\n                {name: "duplicate_transaction_check",\n                 when: "duplicate_detected == true",\n                 action: deny},\n                {name: "high_risk_customer_enhanced_dd",\n                 when: "risk_level == high and enhanced_dd_completed != true",\n                 action: require_review},\n                {name: "velocity_breach",\n                 when: "transactions_in_hour_gt == 10",\n                 action: require_review}\n            ]\n        },\n        ui: {shell: python, routes: [\n            {name: "Dashboard",    path: "/fintech",            component: "FintechDashboard", permission: "fintech:view",     nav_group: "Overview"},\n            {name: "Customers",    path: "/fintech/customers",  component: "CustomerRegistry", permission: "fintech:customers",nav_group: "Customers"},\n            {name: "KYC Queue",    path: "/fintech/kyc",        component: "KYCWorkbench",    permission: "fintech:kyc",      nav_group: "Compliance"},\n            {name: "Transactions", path: "/fintech/transactions",component: "TransactionLedger",permission: "fintech:payments", nav_group: "Payments"},\n            {name: "Wallets",      path: "/fintech/wallets",    component: "WalletManager",   permission: "fintech:wallets",  nav_group: "Payments"},\n            {name: "AML Alerts",   path: "/fintech/aml",        component: "AMLWorkbench",    permission: "fintech:compliance",nav_group: "Compliance"},\n            {name: "Lending",      path: "/fintech/lending",    component: "LoanPortfolio",   permission: "fintech:lending",  nav_group: "Credit"},\n            {name: "Reports",      path: "/fintech/reports",    component: "RegulatoryReports",permission: "fintech:reports",  nav_group: "Regulatory"}\n        ]},\n        theme: {name: fintech_theme, tokens: {\n            "color.primary":   "#0D47A1",\n            "color.accent":    "#00897B",\n            "color.success":   "#1B5E20",\n            "color.warning":   "#F57F17",\n            "color.danger":    "#B71C1C",\n            "surface.canvas":  "#F5F9FF",\n            "surface.panel":   "#FFFFFF",\n            "text.primary":    "#0D1B2A",\n            "text.secondary":  "#546E7A",\n            "border.radius":   "8px",\n            "density":         "comfortable"\n        }, components: {\n            customers:    {icon: "user-check",   status_indicator: "kyc-tier-chip"},\n            transactions: {icon: "arrow-right-left", status_indicator: "txn-status-chip"},\n            aml_alerts:   {icon: "shield-exclamation", status_indicator: "aml-risk-chip"}\n        }}\n    };\n    streaming: {\n        processor: bytewax,\n        stream: "apg.fintech.lifecycle",\n        key: "tenant_id",\n        events: [\n            "kyc_started", "kyc_verified", "kyc_rejected",\n            "payment_initiated", "payment_completed", "payment_failed",\n            "wallet_credited", "wallet_debited", "wallet_frozen",\n            "aml_alert_raised", "aml_cleared", "sar_filed",\n            "loan_disbursed", "repayment_received"\n        ],\n        guardrails: [\n            "unverified_kyc_payment_denied",\n            "sanctions_match_blocked",\n            "duplicate_payment_denied",\n            "velocity_breach_requires_review"\n        ]\n    };\n}\n\nworkflow CustomerOnboarding {\n    steps: str = "registration -> id_verification -> liveness_check -> pep_screening -> risk_scoring -> kyc_approved -> wallet_created -> active";\n    human_tasks: [pep_screening];\n    assignments: {pep_screening: compliance_officer};\n    guards: {\n        liveness_check: "id_document_verified",\n        kyc_approved: "liveness_passed and pep_clear and risk_score_acceptable",\n        active: "wallet_funded or zero_balance_allowed"\n    };\n}\n\nworkflow LoanOrigination {\n    steps: str = "application -> bureau_check -> underwriting -> offer_generated -> accepted -> disbursed";\n    human_tasks: [underwriting];\n    assignments: {underwriting: credit_analyst};\n    guards: {\n        underwriting: "bureau_score available and dsr_within_limit",\n        disbursed: "offer_signed and account_verified"\n    };\n    compensation: {disbursed: reverse_disbursement};\n}\n\nagent FintechRiskOfficer {\n    role: "risk and compliance officer";\n    model: "openai:gpt-4.1-mini";\n    system: "You are a fintech compliance officer for Kenya/East Africa. Review AML alerts, assess transaction patterns, and prepare regulatory submissions to CBK, CMA, and FSCA. Apply FATF recommendations and Kenya AML/CFT framework.";\n    capabilities: [aml_screening_workflow, regulatory_reporting];\n    tools: [transaction_history, customer_risk_profile, watchlist_check, cbk_reporting];\n    memory: vector compliance_memory;\n    configuration: {temperature: 0.0, max_turns: 4};\n    rules: [\n        {name: "no_sar_without_evidence", when: "sar_evidence missing", action: deny}\n    ];\n}\n\napp FintechPlatform {\n    description: "Africa-first fintech platform composed from APG capabilities";\n    capabilities: [FintechCore];\n    agents: [FintechRiskOfficer];\n    routes: ["/fintech", "/fintech/customers", "/fintech/transactions", "/fintech/aml"];\n    theme: {name: fintech_platform_theme, tokens: {"accent": "#00897B", "border.radius": "8px"}};\n    runtime: {target: python, deployment: container, streaming: {processor: bytewax}};\n    deployments: {default: local, container: docker};\n}\n'
